from pathlib import Path

root = Path(__file__).parent

p = root / 'phase75_web.py'
s = p.read_text(encoding='utf-8')
s = s.replace('from agl.project import ProjectStore\n', 'from agl.project import ProjectStore\nfrom agl.qa import load_glossary, run_qa_entry\n')
needle = '''    @app.get("/api/translation-memory")\n    def api_translation_memory(\n        q: str = Query(default=""),\n        language: str = Query(default=""),\n        limit: int = Query(default=50, ge=1, le=200),\n    ):\n        require_project()\n        return {"items": operations.search_translation_memory(q, language, limit)}\n\n'''
insert = needle + '''    @app.get("/api/entries/{entry_id}/assistant-context")\n    def api_entry_assistant_context(entry_id: str):\n        """Return the non-secret context needed by the Translation Editor assistant panel."""\n        require_project()\n        with ProjectStore(project_dir) as store:\n            entry = store.get_entry(entry_id)\n            if entry is None:\n                raise HTTPException(status_code=404, detail="Entry not found.")\n            entries = store.all_entries()\n            target_language = store.meta.get("target_language") or ""\n\n        glossary_path = Path(project_dir) / "glossary.csv"\n        glossary = load_glossary(glossary_path)\n        source = entry.source_text or ""\n        context = entry.context or ""\n        matched_glossary = []\n        for item in glossary:\n            haystack = source if item.case_sensitive else source.lower()\n            needle = item.source_term if item.case_sensitive else item.source_term.lower()\n            if needle and needle in haystack:\n                matched_glossary.append({\n                    "source_term": item.source_term,\n                    "target_term": item.target_term,\n                    "level": item.level,\n                    "case_sensitive": item.case_sensitive,\n                })\n\n        qa_result = run_qa_entry(entry, target_language=target_language, glossary=glossary)\n        qa = [\n            {"level": issue.level, "code": issue.code, "message": issue.message}\n            for issue in qa_result.issues\n        ]\n\n        index = next((i for i, x in enumerate(entries) if x.id == entry.id), -1)\n        neighbors = []\n        if index >= 0:\n            same_file = [x for x in entries if x.file_path == entry.file_path]\n            pos = next((i for i, x in enumerate(same_file) if x.id == entry.id), -1)\n            if pos > 0:\n                prev = same_file[pos - 1]\n                neighbors.append({"relation": "previous", "id": prev.id, "source_text": prev.source_text, "target_text": prev.target_text or "", "status": prev.status.value})\n            if pos >= 0 and pos + 1 < len(same_file):\n                nxt = same_file[pos + 1]\n                neighbors.append({"relation": "next", "id": nxt.id, "source_text": nxt.source_text, "target_text": nxt.target_text or "", "status": nxt.status.value})\n\n        memory = operations.search_translation_memory(source, target_language, limit=8) if source else []\n        exact = [x for x in memory if (x.get("source_text") or "").strip() == source.strip()]\n        return {\n            "entry": {\n                "id": entry.id,\n                "source_text": source,\n                "target_text": entry.target_text or "",\n                "context": context,\n                "file_path": entry.file_path,\n                "engine": entry.engine,\n                "location": entry.location,\n                "note": entry.note or "",\n                "status": entry.status.value,\n                "locked": entry.locked,\n                "ignored": entry.ignored,\n            },\n            "glossary": matched_glossary,\n            "translation_memory": {"exact": exact[:1], "matches": memory},\n            "qa": {"passed": qa_result.passed, "issues": qa},\n            "neighbors": neighbors,\n        }\n\n'''
if needle not in s:
    raise SystemExit('translation-memory endpoint anchor not found')
s = s.replace(needle, insert, 1)
p.write_text(s, encoding='utf-8')

u = root / 'ui_pages.py'
s = u.read_text(encoding='utf-8')
# Add contextual styling.
s = s.replace('.tool-row{padding:7px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface-2);font-size:10px}', '.tool-row{padding:7px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface-2);font-size:10px}.context-card{padding:9px 10px;border:1px solid var(--line);border-radius:9px;background:var(--surface);margin-top:7px}.context-label{font-size:9px;font-weight:850;color:var(--subtle);text-transform:uppercase;letter-spacing:.06em}.context-value{font-size:10px;line-height:1.5;margin-top:4px}.context-highlight{border-left:3px solid var(--accent);padding-left:8px}.assist-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px}.assist-stat{padding:7px 8px;border-radius:8px;background:var(--surface-2);border:1px solid var(--line)}.assist-stat strong{display:block;font-size:13px}.assist-stat span{font-size:9px;color:var(--muted)}')
# Add state var.
s = s.replace("let entries=[],selectedIndex=0,entryTotal=0,projectTotal=0,offset=0;const pageSize=50;let currentTask=null;let currentTaskName='';let reloadTimer=null;let editorDirty=false;let pendingSelect=-1;", "let entries=[],selectedIndex=0,entryTotal=0,projectTotal=0,offset=0;const pageSize=50;let currentTask=null;let currentTaskName='';let reloadTimer=null;let editorDirty=false;let pendingSelect=-1;let assistantContext=null;")
# Replace selectEntry to load context and default to context tab.
old_start = 'function selectEntry(i){if(!entries[i]){clearEditor();return}if(editorDirty&&selectedIndex!==i){pendingSelect=i;openConfirm(\'未保存的修改\',\'当前条目的译文有未保存修改。切换后这些修改会丢失。\',\'放弃修改\',()=>{editorDirty=false;const next=pendingSelect;pendingSelect=-1;selectEntry(next)},true);return}selectedIndex=i;editorDirty=false;'
pos = s.find(old_start)
if pos < 0:
    raise SystemExit('selectEntry anchor not found')
# Find end at switchAssist('ai')
end_token = "switchAssist('ai')}"
end = s.find(end_token, pos)
if end < 0:
    raise SystemExit('selectEntry end not found')
end += len(end_token)
old = s[pos:end]
new = old[:-len("switchAssist('ai')}")] + "assistantContext=null;switchAssist('context');loadAssistantContext() }"
s = s[:pos] + new + s[end:]
# Clear context on clearEditor.
s = s.replace("document.getElementById('entryLock').textContent='—';", "assistantContext=null;document.getElementById('entryLock').textContent='—';", 1)
# Insert loadAssistantContext before updateLength.
anchor = "function updateLength(markDirty=true){"
func = '''async function loadAssistantContext(){\n  const e=entries[selectedIndex]; if(!e)return;\n  const body=document.getElementById('assistBody');\n  if(!body)return;\n  body.innerHTML='<div class="assist-card"><div class="assist-title">Context</div><div class="small">正在读取 Entry 上下文…</div></div>';\n  try{\n    const d=await api('/api/entries/'+encodeURIComponent(e.id)+'/assistant-context');\n    assistantContext=d;\n    renderContextPanel(d);\n  }catch(err){\n    assistantContext=null;\n    body.innerHTML='<div class="assist-card"><div class="assist-title">Context</div><div class="empty-state"><strong>无法读取上下文</strong><div>'+safe(err.message||'')+'</div></div></div>';\n  }\n}\nfunction renderContextPanel(d){\n  const b=document.getElementById('assistBody'); if(!b)return;\n  const e=d.entry||{}; const qa=d.qa||{}; const exact=(d.translation_memory?.exact||[])[0]; const glossary=d.glossary||[]; const neighbors=d.neighbors||[];\n  b.innerHTML='<div class="assist-card"><div class="assist-title">Entry Context</div><div class="context-card context-highlight"><div class="context-label">Scene / Context</div><div class="context-value">'+safe(e.context||'未提供上下文')+'</div></div><div class="context-card"><div class="context-label">File</div><div class="context-value">'+safe(e.file_path||'—')+'</div></div><div class="context-card"><div class="context-label">Engine / Location</div><div class="context-value">'+safe(e.engine||'—')+' · '+safe(JSON.stringify(e.location||{}))+'</div></div>'+(e.note?'<div class="context-card"><div class="context-label">Note</div><div class="context-value">'+safe(e.note)+'</div></div>':'')+'<div class="assist-summary"><div class="assist-stat"><strong>'+safe(glossary.length)+'</strong><span>Matched glossary terms</span></div><div class="assist-stat"><strong>'+safe(qa.issues?.length||0)+'</strong><span>Current QA issues</span></div></div></div>'+(glossary.length?'<div class="assist-card"><div class="assist-title">Glossary Applied</div><div class="tool-list">'+glossary.map(x=>'<div class="tool-row"><strong>'+safe(x.source_term)+' → '+safe(x.target_term)+'</strong><div class="small">'+safe(x.level)+'</div></div>').join('')+'</div></div>':'')+(exact?'<div class="assist-card"><div class="assist-title">Translation Memory</div><div class="small">Exact source match</div><div class="suggestion">'+safe(exact.translated_text||'')+'</div><div class="small" style="margin-top:6px">'+safe(exact.human_reviewed?'Reviewed':'Machine')+(exact.provider?' · '+safe(exact.provider):'')+(exact.model?' · '+safe(exact.model):'')+'</div><div class="header-actions" style="margin-top:8px"><button class="btn sm primary" onclick="useMemoryExact()">Use exact match</button></div></div>':'<div class="assist-card"><div class="assist-title">Translation Memory</div><div class="small">没有精确匹配。</div></div>')+(qa.issues?.length?'<div class="assist-card"><div class="assist-title">QA</div>'+qa.issues.map(x=>'<div class="qa-item"><span class="qa-dot '+(x.level==='error'?'warn':'warn')+'"></span><div><strong>'+safe(x.code)+'</strong><div class="small">'+safe(x.message)+'</div></div></div>').join('')+'</div>':'<div class="assist-card"><div class="assist-title">QA</div><div class="qa-item"><span class="qa-dot ok"></span><div>当前 Entry 没有 QA 问题。</div></div></div>')+(neighbors.length?'<div class="assist-card"><div class="assist-title">Same File</div><div class="tool-list">'+neighbors.map(x=>'<div class="tool-row"><div class="small">'+safe(x.relation)+' · '+safe(x.status)+'</div><div style="margin-top:4px">'+safe(x.source_text)+'</div><div class="small" style="margin-top:3px">'+safe(x.target_text||'—')+'</div></div>').join('')+'</div></div>':'');\n}\nfunction useMemoryExact(){const exact=(assistantContext?.translation_memory?.exact||[])[0];if(!exact)return;const ta=document.getElementById('targetText');if(ta.disabled)return toast('这个条目已锁定，不能编辑。');ta.value=exact.translated_text||'';editorDirty=true;updateLength();document.getElementById('saveState').textContent='● Unsaved changes';toast('已填入 Translation Memory，请保存。')}\n'''
s = s.replace(anchor, func + anchor, 1)
# Make AI panel aware of context and improve suggestion source details.
s = s.replace("if(tab==='ai'){if(entries[selectedIndex]){b.innerHTML='<div class=\"assist-card\"><div class=\"assist-title\">AI Suggestion</div><div class=\"small\">优先使用 Translation Memory；没有匹配时再调用 AI。</div>", "if(tab==='ai'){if(entries[selectedIndex]){b.innerHTML='<div class=\"assist-card\"><div class=\"assist-title\">AI Suggestion</div><div class=\"small\">先参考当前 Entry 的 Context、Glossary 与 Translation Memory；没有合适匹配时再调用 AI。</div>")
# Context branch should render loaded data rather than only two fields.
s = s.replace("}else if(tab==='context'){b.innerHTML='<div class=\"assist-card\"><div class=\"assist-title\">Entry Context</div><div class=\"small\">File</div><div style=\"font-size:10px;font-weight:850;margin-top:3px\">'+safe(document.getElementById('ctxFile').textContent)+'</div><div class=\"small\" style=\"margin-top:10px\">Note</div><div style=\"font-size:10px;font-weight:850;margin-top:3px\">'+safe(document.getElementById('ctxNote').textContent)+'</div></div>'}", "}else if(tab==='context'){if(assistantContext)renderContextPanel(assistantContext);else loadAssistantContext()}")
# Ensure selecting an entry doesn't wipe assistant context due to V13 initial wrappers; after wrappers finish, reload context.
s = s.replace("renderEntryListV13();updateBulkBar();", "renderEntryListV13();updateBulkBar();if(entries[selectedIndex])loadAssistantContext();", 1)
p.write_text(s, encoding='utf-8')
